sys_script.script:
(function validateAdjustmentRequest() {
    gs.debug('[Retail Store Assistant] Validate Adjustment Request: processing new insert');

    var adjNumber = current.getValue('adjustment_number');

    // Validate requested_quantity is a positive integer
    var qtyStr = current.getValue('requested_quantity');
    var qty = parseInt(qtyStr, 10);
    if (isNaN(qty) || qty <= 0) {
        gs.error('[Retail Store Assistant] Validate Adjustment Request: rejected — requested_quantity must be positive, got: ' + qtyStr);
        gs.addErrorMessage('Adjustment Request rejected: requested quantity must be a positive integer greater than zero.');
        current.setAbortAction(true);
        return;
    }
    current.setValue('requested_quantity', qty.toString());
    gs.debug('[Retail Store Assistant] Validate Adjustment Request: quantity validated — ' + qty);

    // Validate requested_direction
    var direction = current.getValue('requested_direction');
    if (direction !== 'increase' && direction !== 'decrease') {
        gs.error('[Retail Store Assistant] Validate Adjustment Request: rejected — requested_direction must be increase or decrease, got: ' + direction);
        gs.addErrorMessage('Adjustment Request rejected: requested direction must be Increase or Decrease.');
        current.setAbortAction(true);
        return;
    }
    gs.debug('[Retail Store Assistant] Validate Adjustment Request: direction validated — ' + direction);

    // Validate idempotency_key uniqueness
    var idempotencyKey = current.getValue('idempotency_key');
    if (!idempotencyKey) {
        gs.error('[Retail Store Assistant] Validate Adjustment Request: rejected — idempotency_key is missing');
        gs.addErrorMessage('Adjustment Request rejected: idempotency_key is required.');
        current.setAbortAction(true);
        return;
    }

    var existing = new GlideRecord('x_1945330_retail_0_adj_req');
    existing.addQuery('idempotency_key', idempotencyKey);
    existing.setLimit(1);
    existing.query();
    if (existing.hasNext()) {
        gs.warn('[Retail Store Assistant] Validate Adjustment Request: duplicate — idempotency_key "' + idempotencyKey + '" already exists');
        gs.addErrorMessage('Adjustment Request rejected: idempotency_key "' + idempotencyKey + '" already exists. Duplicate adjustment requests are not allowed.');
        current.setAbortAction(true);
        return;
    }
    gs.debug('[Retail Store Assistant] Validate Adjustment Request: idempotency_key "' + idempotencyKey + '" is unique');

    // Set default status
    if (!current.getValue('status')) {
        current.setValue('status', 'requested');
    }

    gs.info('[Retail Store Assistant] Validate Adjustment Request: validation passed — adjustment_number=' + adjNumber + ' store=' + current.getValue('store') + ' sku=' + current.getValue('sku') + ' direction=' + direction + ' qty=' + qty);
})();
